        gl.BufferData(GL_SHADER_STORAGE_BUFFER,std::ptrdiff_t(counterBytes),work.data(),GL_DYNAMIC_READ);
        GLint64 stored=0;gl.GetBufferParameteri64v(GL_SHADER_STORAGE_BUFFER,GL_BUFFER_SIZE,&stored);
